'use client'; import {useState} from 'react'; import type {Player} from '@/types/player'; import type {PlayerStats} from '@/types/playerStats';
type Row={player:Player;stats:PlayerStats}; const tabs=[['goals','得点'],['assists','アシスト'],['appearances','出場'],['starts','先発']] as const;
export function RankingTable({rows}:{rows:Row[]}){const [key,setKey]=useState<(typeof tabs)[number][0]>('goals');const sorted=[...rows].sort((a,b)=>b.stats[key]-a.stats[key]||a.stats.appearances-b.stats.appearances||a.player.playerId.localeCompare(b.player.playerId));return <><div className="tabs">{tabs.map(([k,l])=><button className={key===k?'selected':''} key={k} onClick={()=>setKey(k)}>{l}</button>)}</div><div className="ranking">{sorted.map((r,i)=><div className="rank-row" key={r.player.playerId}><b>{String(i+1).padStart(2,'0')}</b><span className="mini-avatar">{r.player.number}</span><div><strong>{r.player.name}</strong><small>{r.player.position} · #{r.player.number}</small></div><em>{r.stats[key]}</em><span>{tabs.find(t=>t[0]===key)?.[1]}</span></div>)}</div></>}
